--- 刷新队伍列表
function HomelandCheckInEntryDialog:RefreshGroupList()
    -- 小组数据
    self.unlockedGroupData = self.comp:GetUnlockedGroupVos()

    -- 第一个加号按钮的数据
    local emptyData = { isEmpty = true}
    local unlockInfo = self.comp:GetNextUnlockInfo()
    if unlockInfo.hasNext then
        emptyData.isBtnCell = true
        if unlockInfo.isUnlocked then
            if unlockInfo.needCost then
                emptyData.type = 2  -- 需要消耗
                emptyData.costItems = unlockInfo.costItems
            else
                emptyData.type = 3  -- 点击添加
            end
        else
            emptyData.type = 1  -- 锁定
            emptyData.unlockDesc = unlockInfo.unlockDesc
        end
    else
        emptyData.isBtnCell = false
    end
    table.insert(self.unlockedGroupData, 1, emptyData)

    -- 刷新列表
    local count = #self.unlockedGroupData
    self:RefreshLoopListViewGroup(count)
end

function HomelandCheckInEntryDialog:RefreshLoopListViewGroup(maxNum)
    if not self.LoopListViewGroup.IsListViewInit then
        self.LoopListViewGroup:InitListView(maxNum, Bind(self, self.OnGroupListGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListViewGroup, maxNum)
    end
    -- 更新首屏显示数量
    self.animTeamCellCount = self:UpdateDisplayItemCount(self.LoopListViewGroup, self.unlockedGroupData)
end

function HomelandCheckInEntryDialog:OnGroupListGetItemByIndex(loopListViewGroup, index)
    if index < 0 then
        return nil
    end
    local luaIndex = index + 1

    local cellData = self.unlockedGroupData[luaIndex]
    if cellData.isEmpty then
        -- 空节点
        if cellData.isBtnCell then
            -- 解锁按钮节点
            local cell = loopListViewGroup:NewListViewItem("InforEntryTeamEmptyCell")
            local LB_cell = GetLuaBehaviour(cell.gameObject, EmptyNodeLuaPath)
            if not cell.IsInitHandlerCalled then
                cell.IsInitHandlerCalled = true
                LB_cell:Init()
            
                -- 延迟动画，第一个节点必播动画
                CfUtils.PlayDelayShowAnimation(cell, index, "InforEntryTeamCell_Cell_Show", "UI_Common_List_Cell_Wait_3")
            end
            local LT_cell = LB_cell.Env
            LT_cell:Refresh(cellData)
            return cell
        else
            -- 布局占位节点
            local cell = loopListViewGroup:NewListViewItem("InforEntryTeamStarCell")
            return cell
        end
    else
        -- 小组节点
        local cell = loopListViewGroup:NewListViewItem("InforEntryTeamCell")
        local LB_cell = GetLuaBehaviour(cell.gameObject, GroupNodeLuaPath)
        if not cell.IsInitHandlerCalled then
            cell.IsInitHandlerCalled = true
            LB_cell:Init()
    
            -- 延迟动画，首屏才播
            if luaIndex <= self.animTeamCellCount + 1 then
                CfUtils.PlayDelayShowAnimation(cell, index, "InforEntryTeamCell_Cell_Show", "UI_Common_List_Cell_Wait_3")
            end
        else
            CfUtils.PlayAnimation(cell, "UI_Common_List_Cell_Idle", true)
        end
        local LT_cell = LB_cell.Env
        LT_cell:Refresh(cellData)
        return cell
    end
end

