        [2] = {attrAddId = 201, color = 0, num = self.comp:GetGlobalAttrAddition(201)},
        [3] = {attrAddId = 301, color = 0, num = self.comp:GetGlobalAttrAddition(301)},
    }
    local count = #self.attrData
    self:RefreshLoopListViewAttr(count)
end

function HomelandCheckInEntryDialog:RefreshLoopListViewAttr(maxNum)
    if not self.LoopListViewAttr.IsListViewInit then
        self.LoopListViewAttr:InitListView(maxNum, Bind(self, self.OnAttrListGetItemByIndex))
        self.LoopListViewAttr:UpdateDisplayItemCount("InforEntryAllTeamAttributeNode")
    else
        GameUtils.ReloadData(self.LoopListViewAttr, maxNum)
    end
end

