--- 计算首屏可以显示的节点数量，做延时出现动画用的
---@param loopListView any
---@param cellDataList any
function HomelandCheckInEntryDialog:UpdateDisplayItemCount(loopListView, cellDataList)
    local teamCell = loopListView:GetItemPrefabConfData("InforEntryTeamCell")
    local spanCell = loopListView:GetItemPrefabConfData("InforEntryTeamStarCell")
    local emptyCell = loopListView:GetItemPrefabConfData("InforEntryTeamEmptyCell")

    local firstCellWidth = 0

    -- 计算第一个特殊节点的宽度
    local d = cellDataList[1]
    if d.isBtnCell then
        -- 空节点
        local rt = emptyCell.mItemPrefab.gameObject:GetComponent(typeof(CS.UnityEngine.RectTransform))
        firstCellWidth = firstCellWidth + emptyCell.mPadding + rt.rect.width
    else
        -- 占位节点
        local rt = spanCell.mItemPrefab.gameObject:GetComponent(typeof(CS.UnityEngine.RectTransform))
        firstCellWidth = firstCellWidth + spanCell.mPadding + rt.rect.width
    end

    -- 计算出去第一特殊节点之后，还剩下的宽度
    local remainWidth = loopListView.ViewPortWidth - firstCellWidth

    -- 剩下的宽度能显示几个teamCell
    local rt = teamCell.mItemPrefab.gameObject:GetComponent(typeof(CS.UnityEngine.RectTransform))
    local count = math.ceil(remainWidth / (teamCell.mPadding + rt.rect.width))
    return count
end

return HomelandCheckInEntryDialog
